# SPDX-License-Identifier: AGPL-3.0-only
import re

def solve(payload):
    tokens = re.findall(r'[0-9]+|//|[()+*-]', payload)
    i = 0
    def atom():
        nonlocal i
        token = tokens[i]
        i += 1
        if token == '+':
            return atom()
        if token == '-':
            return -atom()
        if token == '(':
            value = expression()
            i += 1
            return value
        return int(token)
    def term():
        nonlocal i
        left = atom()
        while i < len(tokens) and tokens[i] in ('*', '//'):
            operator = tokens[i]
            i += 1
            right = atom()
            left = left * right if operator == '*' else int(left / right)
        return left
    def expression():
        nonlocal i
        left = term()
        while i < len(tokens) and tokens[i] in ('+', '-'):
            operator = tokens[i]
            i += 1
            right = term()
            left = left + right if operator == '+' else left - right
        return left
    return expression()

